import { useState } from 'react';

export default function WeddingService() {
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [request, setRequest] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();

    const body = {
      name,
      phone,
      email,
      request,
      serviceType: "Tiệc cưới" // tự động gán đúng loại dịch vụ
    };

    try {
      const res = await fetch('http://localhost:5000/api/requests', {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body)
      });

      if (res.ok) {
        alert("Đã gửi thành công!");
        setName(""); setPhone(""); setEmail(""); setRequest("");
      } else {
        alert("Có lỗi xảy ra khi gửi yêu cầu.");
      }
    } catch (err) {
      console.error(err);
      alert("Lỗi kết nối server.");
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input type="text" value={name} onChange={e => setName(e.target.value)} required />
      <input type="text" value={phone} onChange={e => setPhone(e.target.value)} />
      <input type="email" value={email} onChange={e => setEmail(e.target.value)} required />
      <textarea value={request} onChange={e => setRequest(e.target.value)} required />
      <button type="submit">Đặt ngay</button>
    </form>
  );
}
